mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode, pro.P_Name as pName, c1.C_Name as vpCName, c1.C_Name_History as vpCNameHistory, c1.C_Abbreviation as vpCAbbName, pro.P_Name_History as pNameHistory, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, sd.D_Name as vpDName, sec.Sec_Name as secName, qst.Qst_Name qstName, qst.Qst_Score as qstScore, qst.Qst_Punish as qstPunish, mn.* from Qs_Violation_Punishment mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Department sd on sd.D_ID=mn.Vp_D_Id left join SYS_Company c1 on c1.C_Id=mn.Vp_C_Id left join Qs_Type qst on qst.Qst_Id=mn.Qst_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Sec_Id=#{params.secId}
and mn.Vp_C_Id=#{params.vpCId}
and mn.Vp_D_Id = #{params.vpDId}
and qst.Qst_Name like concat('%',#{params.qstName},'%')
and likeCname(#{params.vpCName},c1.C_Id)=true
and c1.C_Name like concat('%',#{params.vpCName},'%')
and mn.Vp_Type=#{params.vpType}
and mn.Vp_State=#{params.vpState}
and mn.Vp_Level=#{params.vpLevel}
and mn.Vp_Create_Uname like concat('%',#{params.vpCreateUname},'%')
and mn.Vp_Code like concat('%',#{params.vpCode},'%')
and mn.Vp_Page_Code like concat('%',#{params.vpPageCode},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and mn.Vp_State in
#{state}
order by mn.${params.sortFiled} ${params.sortType}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Vp_Create_Time desc
